// Mode: Run Once for All Items

// Try to get data from both possible inputs
const items = $input.all();

// Extract 'scenes' and 'scenes_temp' from available inputs
let scenes = null;
let scenesTemp = null;

for (const item of items) {
  const j = item.json;
  if (Array.isArray(j.scenes) && j.scenes.length > 0) {
    scenes = j.scenes;
  }
  if (Array.isArray(j.scenes_temp) && j.scenes_temp.length > 0) {
    scenesTemp = j.scenes_temp;
  }
}

// Pick whichever exists
const finalScenes = scenes || scenesTemp || [];

// Optional: log what was chosen
console.log(`✅ Using ${scenes ? "scenes" : scenesTemp ? "scenes_temp" : "none"} array`);
console.log(`Total scenes: ${finalScenes.length}`);

return [
  {
    json: {
      final_scenes: finalScenes,
      meta: {
        source: scenes ? "scenes" : scenesTemp ? "scenes_temp" : "none",
        total: finalScenes.length,
      },
    },
  },
];

return items.map(item => {
  const b = item.binary?.data;
  if (b) {
    b.fileName = (b.fileName && b.fileName.toLowerCase().endsWith('.mp4'))
      ? b.fileName
      : (b.fileName ? `${b.fileName}.mp4` : 'clip.mp4');
    b.mimeType = 'video/mp4';
  }
  return item;
});

// Code / Function node: combine current items
const clip_ids = items.map(i => i.json.clip_id).filter(Boolean);
if (!clip_ids.length) throw new Error('No clip_ids on input items');

return [{
  json: {
    clip_ids,
    transition_duration: 0.2,
    output_name: 'merged.mp4'
  }
}];
